using System;using System.Linq;using UnityEditor;using UnityEngine;using UnityEngine.UI;using Mirror;using MultiFPS;using MultiFPS.Gameplay;using MultiFPS.Gameplay.RiftCombat;using MultiFPS.Gameplay.RiftEnemies;using ROM.Horde;using ROM.UI.Sprint01;
namespace ROM.EditorTools {public static partial class RiftJournalProbe {
 static int pooledInstance;static RiftEnemySpawnZone poolZone;static RiftEnemyPopulation poolPopulation;static RiftEnemyAgent recycled;
 public static void RunInventory(){foreach(string path in new[]{WarriorRebuildBuilder.PlayerPath,WarriorRebuildBuilder.LobbyPath}){var root=PrefabUtility.LoadPrefabContents(path);try{foreach(var animator in root.GetComponentsInChildren<Animator>(true))if(!animator.GetComponent<RiftFootstepEvents>())animator.gameObject.AddComponent<RiftFootstepEvents>();PrefabUtility.SaveAsPrefabAsset(root,path);}finally{PrefabUtility.UnloadPrefabContents(root);}}Run();SessionState.SetBool(Key+"Inventory",true);}
 static void InventoryTick(CharacterInstance actor,PlayerInstance player){
 if(step==700){Check(actor.GetComponent<WarriorAvatar>().Animator.GetComponent<RiftFootstepEvents>(),"Native Animator receives both footstep events");var animator=actor.GetComponent<WarriorAvatar>().Animator;animator.gameObject.SendMessage("FootL",SendMessageOptions.RequireReceiver);animator.gameObject.SendMessage("FootR",SendMessageOptions.RequireReceiver);PlayerPrefs.SetInt(RiftVillageSupplies.Key(0),3);PlayerPrefs.SetInt(RiftVillageSupplies.Key(1),2);actor.Health.ServerSetVitals(170,10);player.GetComponent<RiftVillagePlayer>().PotionReadyAt=0;Press(UnityEngine.InputSystem.Key.I);Advance(.7);return;}
 if(step==701){Press();var view=UnityEngine.Object.FindFirstObjectByType<RiftInventoryView>();Check(view,"I opens the gameplay inventory");Check(view.GetComponentsInChildren<Button>().Count(b=>b.name.StartsWith("Empty bag cell"))==22,"Bag displays actual supplies plus clearly reserved cells");Check(view.GetComponentsInChildren<Text>().Any(t=>t.text=="× 3"),"Inventory reads real supply quantity");Capture("inventory");view.GetComponentsInChildren<Button>().First(b=>b.GetComponentInChildren<Text>()?.text=="USAR POCIÓN").onClick.Invoke();Advance(.5);return;}
 if(step==702){var view=UnityEngine.Object.FindFirstObjectByType<RiftInventoryView>();Check(RiftVillageSupplies.Count(0)==2,"Inventory use consumes one real potion");Check(!view.GetComponentsInChildren<Button>().First(b=>b.GetComponentInChildren<Text>()?.text=="USAR POCIÓN").interactable,"Shared cooldown disables inventory use");Check(view.GetComponentsInChildren<Text>().Any(t=>t.text.Contains("Recarga compartida:")),"Inventory displays live shared cooldown");view.GetComponentsInChildren<Button>().First(b=>b.name=="Supply slot 1").onClick.Invoke();Advance(.3);return;}
 if(step==703){var view=UnityEngine.Object.FindFirstObjectByType<RiftInventoryView>();Check(view.GetComponentsInChildren<Text>().Any(t=>t.text.Contains("Recupera 75%")),"Selecting major potion shows its own healing value");MultiFPS.UI.UIPauseMenu._instance.ShowPauseMenu(false);var world=ROM.Horde.Horde.Instance;world.enabled=false;poolPopulation=world.GetComponent<RiftEnemyPopulation>();poolPopulation.enabled=false;poolZone=poolPopulation.Zones.First(z=>z.Encounter&&!z.Encounter.MiniBoss);poolZone.Enemies=new[]{new RiftEnemySpawnChoice{Enemy=UnityEditor.AssetDatabase.LoadAssetAtPath<RiftEnemyDefinition>(LittleDemonBuilder.Root+"/LittleDemon.asset"),Weight=1}};poolZone.Spawned=poolZone.Defeated=0;recycled=poolPopulation.ServerSpawn(poolZone);Check(recycled,"Pool supplies a real native enemy");pooledInstance=recycled.GetInstanceID();recycled.Despawn();poolZone.Spawned=0;recycled=poolPopulation.ServerSpawn(poolZone);Check(recycled.GetInstanceID()==pooledInstance&&NetworkServer.spawned.ContainsKey(recycled.netId),"Retired enemy is reused and network-spawned again");Check(!recycled.Dead&&recycled.Health.CurrentHealth==recycled.Definition.Health&&recycled.Body.enabled,"Reused enemy resets health, death state and collider");actor.ServerTeleport(recycled.transform.position-Vector3.forward*2,0);Advance(.4);return;}
 if(step==704){recycled.Health.Server_ChangeHealthStateRaw(999999,0,AttackType.hitscan,actor.Health,0);Check(recycled.Dead,"Reused enemy can die normally");recycled.Despawn();poolZone.Spawned=poolZone.Defeated=0;recycled=poolPopulation.ServerSpawn(poolZone);Check(recycled&&recycled.GetInstanceID()==pooledInstance&&!recycled.Dead,"Dead enemy can be reset and reused");Check(GameSync.Singleton.Healths.Obj[recycled.Health.DNID]==recycled.Health,"Reused enemy re-registers its new network identity in the damage registry");recycled.Despawn();Finish(true);return;}
 }
}}
